{
  "technical_and_design_decisions": [
    "Implement the Reactor (U1) and RxJava (U7) processors as standard Spring XD processor modules using the XD module framework's Java/annotation configuration model, mirroring the existing Spark module pattern, so that a module only needs to declare its processor class to work.",
    "Expose additional Reactor module configuration through the XD module options mechanism (option metadata plus option commands at stream definition time), consistent with how other modules are configured.",
    "Implement the Redis aggregation of field-value counters (U3/U4) with Spring Data Redis, using atomic Redis hash/increment operations so counters can be updated continuously as data is ingested.",
    "Isolate Hadoop tests (U5) by creating a dedicated Gradle subproject for them and removing the DIRT module's test dependencies on Hadoop test fixtures, which restores correct Eclipse classpath file generation.",
    "Implement XD+YARN acceptance tests on EC2 (U6) as a separate CI job that provisions a YARN cluster on EC2 via scripts, deploys XD, runs tests exercising simple XD features through the shell/REST interfaces, and tears the environment down afterwards.",
    "For the HTTP source module (U8), replace the hard-coded 1MB HttpChunkAggregator limit with a configurable property exposed through servers.yml, keeping 1MB as the default for backward compatibility.",
    "Perform the Reactor 2.0 RC1 upgrade (U2) as a dependency/build change plus targeted API-migration fixes, without redesigning existing module code."
  ],
  "assumptions": [
    "U4 is an exact duplicate of U3, so the work is estimated only once (under the U3 activities).",
    "A single developer performs all work; estimates include analysis/design, implementation, unit and integration testing, code-review rework, and documentation, and exclude project management, release, and deployment operations.",
    "The target codebase is the existing Spring XD multi-module Gradle project consistent with the Reactor 2.0 RC1 timeframe, and required infrastructure (CI server, AWS EC2 account, Redis and Hadoop/YARN test environments) is available.",
    "The developer is experienced with Spring XD internals, Reactor, RxJava, Redis, and Hadoop/YARN, so no learning/ramp-up time is included.",
    "For U6, effort covers automated provisioning scripts, the acceptance test suite, and CI integration; ongoing cloud usage costs and manual cluster administration are out of scope.",
    "Estimates are stated per user story independently; any synergies from implementing related stories together (e.g., U1 after U2) are not taken into account."
  ],
  "activities": [
    {
      "activity_id": "1.1",
      "activity_name": "Design Reactor processor module contract",
      "activity_description": "U1: Analyze existing Spark and RxJava module implementations and define the minimal contract (processor class declaration) and integration points for a Reactor-based processor module.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "1.2",
      "activity_name": "Implement Reactor processor module plugin",
      "activity_description": "U1: Implement the plugin that registers and wires a Reactor processor module into XD streams with minimal configuration.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "1.3",
      "activity_name": "Implement module option support for Reactor processor",
      "activity_description": "U1: Add support for additional configuration of the Reactor processor module via well-known module option commands, including option metadata.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "1.4",
      "activity_name": "Test Reactor processor module",
      "activity_description": "U1: Write unit and integration tests covering the Reactor processor module, its minimal configuration, and module options.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "1.5",
      "activity_name": "Document Reactor processor module",
      "activity_description": "U1: Document usage, minimal setup, and available module options for the Reactor processor module.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "2.1",
      "activity_name": "Update build to Reactor 2.0 RC1",
      "activity_description": "U2: Update Gradle build files to Reactor 2.0 RC1 and align dependent library versions.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "2.2",
      "activity_name": "Resolve Reactor 2.0 RC1 API incompatibilities",
      "activity_description": "U2: Fix compilation errors and adapt code to Reactor 2.0 RC1 API changes across affected modules.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "2.3",
      "activity_name": "Regression-test Reactor upgrade",
      "activity_description": "U2: Run the full regression test suite and fix failures caused by the Reactor 2.0 RC1 upgrade.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "3.1",
      "activity_name": "Port field-value counter aggregation specs and identify gaps",
      "activity_description": "U3/U4: Port the specifications from the previous aggregate field-value counter implementation and identify functional gaps for the Redis-based version.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "3.2",
      "activity_name": "Implement Redis field-value counter aggregation",
      "activity_description": "U3/U4: Implement the Redis-based aggregation over field-value counters so counters are continuously written to Redis as data is ingested.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "3.3",
      "activity_name": "Test Redis aggregation",
      "activity_description": "U3/U4: Write unit and integration tests for the Redis aggregation using an embedded/test Redis instance, covering continuous updates of counters.",
      "most_likely_effort": 14
    },
    {
      "activity_id": "3.4",
      "activity_name": "Update reference documentation for Redis aggregation",
      "activity_description": "U3/U4: Update the reference documentation describing the Redis-based field-value counter aggregation.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "4.1",
      "activity_name": "Create separate Hadoop test project",
      "activity_description": "U5: Create a dedicated Gradle subproject and move the Hadoop tests out of the DIRT project into it.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "4.2",
      "activity_name": "Update build configuration for test isolation",
      "activity_description": "U5: Adjust Gradle build configuration, remove the DIRT dependency on Hadoop tests, and fix the Eclipse classpath file generation.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "4.3",
      "activity_name": "Verify builds after Hadoop test isolation",
      "activity_description": "U5: Verify CI build execution of the relocated Hadoop tests and correct Eclipse project import/classpath generation.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "5.1",
      "activity_name": "Create EC2/YARN provisioning scripts",
      "activity_description": "U6: Create scripts to provision an XD-on-YARN test cluster on EC2 for acceptance testing, including setup and teardown.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "5.2",
      "activity_name": "Implement XD+YARN acceptance tests",
      "activity_description": "U6: Implement acceptance tests that verify simple XD features running on YARN on the provisioned EC2 cluster.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "5.3",
      "activity_name": "Integrate YARN acceptance tests into CI",
      "activity_description": "U6: Integrate the XD+YARN-on-EC2 acceptance tests into the CI build cycle so they run on every build.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "6.1",
      "activity_name": "Design RxJava processor module integration",
      "activity_description": "U7: Design how an RxJava-based processor integrates with XD streams and the module framework.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "6.2",
      "activity_name": "Implement RxJava processor module",
      "activity_description": "U7: Implement the RxJava-based processor module so users can leverage RxJava APIs for data computations.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "6.3",
      "activity_name": "Test RxJava processor module",
      "activity_description": "U7: Write unit and integration tests for the RxJava processor module.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "6.4",
      "activity_name": "Document RxJava processor module",
      "activity_description": "U7: Document usage of the RxJava processor module with examples of RxJava-based computations.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "7.1",
      "activity_name": "Expose HTTP message size property",
      "activity_description": "U8: Replace the hard-coded 1MB HttpChunkAggregator limit in the HTTP source module with a configurable property.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "7.2",
      "activity_name": "Wire message size override via servers.yml",
      "activity_description": "U8: Wire the new message size property through servers.yml so the default message handling behavior of the HTTP source module can be overridden.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "7.3",
      "activity_name": "Test configurable HTTP message size",
      "activity_description": "U8: Write unit and integration tests verifying default behavior and overrides of the HTTP message size setting.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "7.4",
      "activity_name": "Document HTTP message size property",
      "activity_description": "U8: Document the new HTTP source message size property in the servers.yml reference documentation.",
      "most_likely_effort": 2
    }
  ],
  "reported_total": {
    "most_likely_effort": 276
  }
}
